/* Region registry - see regions.h for why this is its own file.
 *
 * The shape, one paragraph (REGIONS.md sections 3.1-3.5):
 *
 *   - A region is a **slot in a registry**, never a first-class value. What the library
 *     hands out is a handle: `{ index, generation }`, a plain copyable value.
 *   - Every slot carries a generation. Dropping a region bumps its generation, so a handle
 *     that outlived its region fails the check instead of reading freed memory; the library
 *     turns that into `failure(staleHandle)` with a source position (ruling: a bug traps, a
 *     condition is a value - REGIONS.md section 3.3).
 *   - Regions and arena blocks are **one tree**: a region's parent is either another region
 *     or the arena level that created it. Dropping a region drops its whole subtree, and
 *     leaving a block drops every region still hanging off that level. That is the hook the
 *     generator emits, one line per release point.
 *   - Membership is the whole point: because the owner is the parent (not the handle),
 *     "copy the handle" and "two owners free the same slot" cannot happen, and a free list
 *     cannot grow a cycle out of user data.
 *
 * A region is **not** a second allocator, and an arena is **not** a stack. The arena is
 * where lifetime comes from (its release point is the block that owns it); a region-backed
 * container puts a **pointer into that same arena**, the pointer names its region, and the
 * region holds the container's data structure. The region's own bookkeeping - slot table,
 * free list, generation, parent/child links - lives in that arena too, as a tree of
 * pointers; clearing walks the tree and marks the slots reusable. Nothing is freed piece by
 * piece: the arena reclaims everything when its block goes, which is why the region's
 * lifetime is simply the lifetime of the arena it was created in.
 */

#include "regions.h"

/* The runtime text below is the only copy of this logic: it is what runs, so it is what has
 * to be read and tested (`tests/region/` compiles the emitted C with -Wall -Wextra -Werror
 * and runs it under ASan). It references `extc_arena`, so it is appended after the arena
 * runtime. Split across several `bufPuts` calls because a single literal longer than the
 * 4095 characters C99 requires compilers to support draws -Woverlength-strings. */
void regionsEmitRuntime(Arena *a, Buf *out) {
    (void)a;
    bufPuts(out, "/* ---- region registry (REGIONS.md) ----\n * A region is a slot here, never a value: the library hands out `{ index, generation }`,\n * and dropping bumps the generation, so a handle that outlived its region fails a check\n * instead of reading freed memory.\n *\n * The model, one paragraph: an arena is where lifetime comes from, not a stack. A\n * region-backed container stores a pointer in that same arena; the pointer names its\n * region, and the region holds the container's data structure. The bookkeeping below -\n * slot table, free list, generation, parent/child links - lives in that arena too, as a\n * tree of pointers. Clearing walks the tree and marks slots reusable; the memory itself\n * goes back when the arena's block goes, which is why a region's lifetime is exactly the\n * lifetime of the arena it was created in. Nested regions (a container of containers) are\n * logically nested but share one arena, so they all leave together.\n *\n * The registry is per frame (section 3.5): entering a frame pushes a mark and records the\n * frame's arena array, so a region created at block level L allocates from `arenas[L]` -\n * the same arena the block's own allocations use, with the same promotion rules, escape\n * analysis and level numbering. A child region inherits its parent's arena.\n *\n * Emitted only for a program that declares a region extern. */\ntypedef struct ExtcRegion {\n    uint64_t generation;\n    int64_t  parent;        /* parent region, or -1 when this one hangs off a level */\n    int64_t  frame;         /* the frame that created it */\n    int64_t  level;         /* arena level inside that frame (parent < 0 only) */\n    int64_t  firstChild;    /* child regions */\n    int64_t  nextSibling;   /* the parent's child list */\n    int64_t  frameNext;     /* the frame's list of top-level regions */\n    int64_t  freeNext;      /* the free list */\n    extc_arena *arena;      /* the arena its data lives in (borrowed, never owned) */\n    int64_t  live;\n} ExtcRegion;\ntypedef struct ExtcFrame {\n    int64_t     firstRegion, parent;\n    extc_arena *arenas;     /* the frame's arena array; regions allocate from it */\n    int64_t     narenas;\n} ExtcFrame;\nstatic ExtcRegion *extc_regions        = NULL;\nstatic int64_t     extc_regionCap      = 0;\nstatic int64_t     extc_regionLiveN    = 0;\nstatic int64_t     extc_regionFreeHead = -1;\nstatic ExtcFrame *extc_frames          = NULL;\nstatic int64_t     extc_frameCap       = 0;\nstatic int64_t     extc_frameTop       = -1;   /* the innermost frame */\nint64_t extc_region_live(void) { return extc_regionLiveN; }\nint64_t extc_region_capacity(void) { return extc_regionCap; }\nint64_t extc_region_frameDepth(void) { return extc_frameTop + 1; }\n/* Entering a frame: push a mark and remember where its arenas are. */\nint64_t extc_region_frameEnter(extc_arena *arenas, int64_t narenas) {\n    int64_t id = extc_frameTop + 1;\n    if (id >= extc_frameCap) {\n        int64_t want = extc_frameCap ? extc_frameCap * 2 : 64;\n");
    bufPuts(out, "        ExtcFrame *grown = (ExtcFrame *)realloc(extc_frames, (size_t)want * sizeof *grown);\n        if (!grown) return -1;\n        extc_frames = grown; extc_frameCap = want;\n    }\n    extc_frames[id].firstRegion = -1;\n    extc_frames[id].parent      = extc_frameTop;\n    extc_frames[id].arenas      = arenas;\n    extc_frames[id].narenas     = narenas;\n    extc_frameTop = id;\n    return id;\n}\n/* The arena a region at this level allocates from: the block's own arena. Level 0 means\n * \"the frame's body\", which is arenas[1]; anything out of range falls back there too,\n * because a wrong arena is worse than a conservative one. */\nstatic extc_arena *extc_region_arenaOf(int64_t frame, int64_t level) {\n    ExtcFrame *f = &extc_frames[frame];\n    if (!f->arenas || f->narenas <= 1) return f->arenas;\n    if (level < 1 || level >= f->narenas) return &f->arenas[1];\n    return &f->arenas[level];\n}\nstatic void extc_region_freeSelf(int64_t rid) {\n    ExtcRegion *r = &extc_regions[rid];\n    r->live = 0; r->level = 0; r->parent = -1; r->arena = NULL;\n    r->firstChild = -1;\n    r->freeNext = extc_regionFreeHead;\n    extc_regionFreeHead = rid;\n    extc_regionLiveN--;\n}\nstatic void extc_region_unlinkFrame(int64_t rid) {\n    int64_t fi = extc_regions[rid].frame;\n    if (fi < 0) return;\n    {\n        int64_t *link = &extc_frames[fi].firstRegion;\n        while (*link >= 0) {\n            if (*link == rid) { *link = extc_regions[rid].frameNext; break; }\n            link = &extc_regions[*link].frameNext;\n        }\n    }\n}\nvoid extc_region_drop(int64_t rid) {\n    int64_t child, parent;\n    if (rid < 0 || rid >= extc_regionCap || !extc_regions[rid].live) return;\n    child = extc_regions[rid].firstChild;\n    while (child >= 0) {\n        int64_t next = extc_regions[child].nextSibling;\n        extc_region_drop(child);\n        child = next;\n    }\n    parent = extc_regions[rid].parent;\n    if (parent >= 0) {\n        int64_t *link = &extc_regions[parent].firstChild;\n        while (*link >= 0) {\n            if (*link == rid) { *link = extc_regions[rid].nextSibling; break; }\n            link = &extc_regions[*link].nextSibling;\n        }\n    } else {\n        extc_region_unlinkFrame(rid);\n    }\n    extc_region_freeSelf(rid);\n}\nint64_t extc_region_new(int64_t parent, int64_t level) {\n    int64_t idx, fi = extc_frameTop;\n    ExtcRegion *r;\n    if (fi < 0) return -1;                     /* outside any frame: no owner, no region */\n    if (extc_regionFreeHead >= 0) {\n        idx = extc_regionFreeHead;\n        extc_regionFreeHead = extc_regions[idx].freeNext;\n    } else {\n        int64_t want = extc_regionCap ? extc_regionCap * 2 : 64, i;\n        ExtcRegion *grown = (ExtcRegion *)realloc(extc_regions, (size_t)want * sizeof *grown);\n        if (!grown) return -1;\n        for (i = extc_regionCap; i < want; i++) {\n            grown[i].generation = 0; grown[i].parent = -1; grown[i].frame = -1;\n            grown[i].level = 0; grown[i].firstChild = -1; grown[i].nextSibling = -1;\n");
    bufPuts(out, "            grown[i].frameNext = -1; grown[i].freeNext = -1; grown[i].arena = NULL;\n            grown[i].live = 0;\n        }\n        extc_regions = grown; idx = extc_regionCap; extc_regionCap = want;\n    }\n    r = &extc_regions[idx];\n    if (r->live) return -1;                    /* a free slot is never live */\n    r->generation++;                           /* first life of a fresh slot: 1 */\n    r->live = 1; r->parent = parent; r->level = level; r->frame = fi;\n    r->firstChild = -1; r->nextSibling = -1; r->frameNext = -1;\n    if (parent >= 0) {\n        r->arena = extc_regions[parent].arena;     /* nested regions share one arena */\n        r->nextSibling = extc_regions[parent].firstChild;\n        extc_regions[parent].firstChild = idx;\n    } else {\n        r->arena = extc_region_arenaOf(fi, level);\n        r->frameNext = extc_frames[fi].firstRegion;\n        extc_frames[fi].firstRegion = idx;\n    }\n    extc_regionLiveN++;\n    return idx;\n}\nuint64_t extc_region_generation(int64_t rid) {\n    if (rid < 0 || rid >= extc_regionCap || !extc_regions[rid].live) return 0;\n    return extc_regions[rid].generation;\n}\n/* Keep the region, mark its slots reusable: the tree is walked and dropped, the memory\n * stays in the arena (nothing here frees piece by piece - the arena is the only release\n * point). A child region goes with its parent, because the parent's epoch moved on. */\nvoid extc_region_reset(int64_t rid) {\n    int64_t child;\n    if (rid < 0 || rid >= extc_regionCap || !extc_regions[rid].live) return;\n    child = extc_regions[rid].firstChild;\n    while (child >= 0) {\n        int64_t next = extc_regions[child].nextSibling;\n        extc_region_drop(child);\n        child = next;\n    }\n    extc_regions[rid].firstChild = -1;\n}\n/* The block hook: a region created at this frame's level dies with that block. */\nvoid extc_region_releaseLevel(int64_t frame, int64_t level) {\n    int64_t rid;\n    if (frame < 0 || frame > extc_frameTop || level <= 0) return;\n    rid = extc_frames[frame].firstRegion;\n    while (rid >= 0) {\n        int64_t next = extc_regions[rid].frameNext;\n        if (extc_regions[rid].level == level) extc_region_drop(rid);\n        rid = next;\n    }\n}\n/* The frame hook: everything the frame created, including what its blocks left behind. */\nvoid extc_region_frameLeave(int64_t frame) {\n    int64_t rid;\n    if (frame < 0 || frame > extc_frameTop) return;\n    rid = extc_frames[frame].firstRegion;\n    while (rid >= 0) {\n        int64_t next = extc_regions[rid].frameNext;\n        extc_region_drop(rid);\n        rid = next;\n    }\n    if (frame == extc_frameTop) extc_frameTop = extc_frames[frame].parent;\n}\n/* Memory for a container's data structure, out of the arena the region lives in. It is\n * the arena allocator, so the zeroing promise and the failure behaviour are the same as\n * every other allocation; what differs is only who decides when it is reusable. The\n * position is \"<region>\" because the allocation is the library's, not a source line the\n");
    bufPuts(out, " * user wrote - the same reason section 3.3 wants @trackCaller for traps. */\nuint8_t *extc_region_alloc(int64_t rid, int64_t bytes) {\n    ExtcRegion *r;\n    if (rid < 0 || rid >= extc_regionCap || !extc_regions[rid].live) return NULL;\n    r = &extc_regions[rid];\n    if (!r->arena) return NULL;\n    return (uint8_t *)extc_arena_alloc(r->arena, bytes, \"<region>\", 0);\n}\n");
}
